-- 主函数
function MoveNpc_Main()
	for i,v in pairs (MoveNpc_NpcInfo) do
		MoveNpc_Move(v)
	end
	
	-- 判断是否是无赠品服务器
	if SpecialServer_ChkNoGiftServer() then
		for i,v in pairs (MoveNpc_NpcInfo_NoGift) do
			MoveNpc_Move(v)
			if MoveNpc_NpcInfo[i] ~= nil then
				MoveNpc_NpcInfo[i]["IsSpecial"] = true
			end
		end
	end
end
-- 移动NPC
function MoveNpc_Move(v)
	local nNpcId = v["NpcId"]
	-- 获取NPC所在地图
	-- local nNpcMapId = Get_NpcMapID(nNpcId)
	local nNpcMapId,nPosX,nPosY = NpcPosition_Get(nNpcId)
		
	-- 该NPC存在
	if nNpcMapId == nil or v["IsSpecial"] then
		return
	end
	
	local nNewActivityTime = v["NewActivetyTime"]
	local nActivityTime = v["ActivetyTime"]
	local nActivetyMapId = v["ActivetyMapId"]
	local nActivetyPosX = v["ActivetyPosX"]
	local nActivetyPosY = v["ActivetyPosY"]
	local nAfterActivetyMapId = v["AfterActivetyMapId"] or 5000
	local nAfterActivetyPosX = v["AfterActivetyPosX"] or 120
	local nAfterActivetyPosY = v["AfterActivetyPosY"] or 60
	local nGlobalId = v["GlobalId"]
	local nGlobalData = v["GlobalData"] or 1
	local nOldGlobalData = v["GlobalData"] or 0
	local nPos = v["GlobalPos"] or 0
	local bMove = false

	-- 判断是否在活动时间内
	if nActivityTime ~= nil then
		-- 配多个活动时间
		if type(nActivityTime) == "table" then
			for _,nTime in pairs(nActivityTime) do
				if Sys_ChkFullTime(nTime) then
					bMove = true
					break
				end
			end
			
		-- 配一个活动时间
		elseif Sys_ChkFullTime(nActivityTime) then
			bMove = true
		end
	end
	
	-- 判断是否是动态存储表控制活动的开启
	if nGlobalId ~= nil then
		local nData = Get_SysDynaGlobalData(nGlobalId,nPos)
		-- 只上老服
		if v["OldSever"] ~= nil then
			if nData ~= nOldGlobalData then
				bMove = false
			end
			
		elseif nData >= nGlobalData then
			if nNewActivityTime ~=nil then
				if Sys_ChkFullTime(nNewActivityTime) then
					bMove = true
				else
					bMove = false
				end
			else
				bMove = true
			end
		end
	end
	
	


	
	if bMove == true then
		-- 判断是否已在活动地图内
		if nNpcMapId ~= nActivetyMapId then
			Npc_MoveNpcPos(nNpcId,nActivetyMapId,nActivetyPosX,nActivetyPosY)
		end
	else
		-- 判断是否已在该地图内
		if nNpcMapId ~= nAfterActivetyMapId then
			Npc_MoveNpcPos(nNpcId,nAfterActivetyMapId,nAfterActivetyPosX,nAfterActivetyPosY)
		end
	end
end

function MoveNpc_ChgNpcActivetyTime(nNpcId)
	if MoveNpc_NpcInfo[nNpcId] ~= nil then
		MoveNpc_NpcInfo[nNpcId]["ActivetyTime"] = "2016-03-17 00:00 2016-03-30 23:59"
		MoveNpc_NpcInfo[nNpcId]["NewActivetyTime"] = "2016-03-17 00:00 2016-03-30 23:59"
	end
	
	if MoveNpc_NpcInfo_NoGift[nNpcId] ~= nil then
		MoveNpc_NpcInfo_NoGift[nNpcId]["ActivetyTime"] = "2016-03-17 00:00 2016-03-30 23:59"
		MoveNpc_NpcInfo_NoGift[nNpcId]["NewActivetyTime"] = "2016-03-17 00:00 2016-03-30 23:59"
	end
end

-- 设置移动NPC的数据
function MoveNpc_SetNpcInfo(nNpcId,tInfo)
	local tNpcInfo = MoveNpc_NpcInfo[nNpcId]
	local bNoGift = false
	if SpecialServer_ChkNoGiftServer() then
		tNpcInfo = MoveNpc_NpcInfo_NoGift[nNpcId]
		bNoGift = true
	end
	if tNpcInfo ~= nil then
		return
	end
	if not bNoGift then
		if tInfo["Pos"] == nil or tInfo["Pos"]["Ordinary"] == nil then
			return
		end
		MoveNpc_NpcInfo[nNpcId] = {}
		MoveNpc_NpcInfo[nNpcId]["ActivetyTime"] = tInfo["ActivityTime"]
		MoveNpc_NpcInfo[nNpcId]["NpcId"] = nNpcId
		MoveNpc_NpcInfo[nNpcId]["ActivetyMapId"] = tInfo["Pos"]["Ordinary"]["MapId"]
		MoveNpc_NpcInfo[nNpcId]["ActivetyPosX"] = tInfo["Pos"]["Ordinary"]["PosX"]
		MoveNpc_NpcInfo[nNpcId]["ActivetyPosY"] = tInfo["Pos"]["Ordinary"]["PosY"]
		MoveNpc_NpcInfo[nNpcId]["AfterActivetyMapId"] = 5000
		MoveNpc_NpcInfo[nNpcId]["AfterActivetyPosX"] = 100
		MoveNpc_NpcInfo[nNpcId]["AfterActivetyPosY"] = 100
		MoveNpc_NpcInfo[nNpcId]["GlobalId"] = tInfo["GlobalId"]
		MoveNpc_NpcInfo[nNpcId]["GlobalData"] = tInfo["GlobalData"]
		MoveNpc_NpcInfo[nNpcId]["GlobalPos"] = tInfo["GlobalPos"]
	else
		if tInfo["Pos"] == nil or tInfo["Pos"]["NoGift"] == nil then
			return
		end
		MoveNpc_NpcInfo_NoGift[nNpcId] = {}
		MoveNpc_NpcInfo_NoGift[nNpcId]["ActivetyTime"] = tInfo["ActivityTime"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["NpcId"] = nNpcId
		MoveNpc_NpcInfo_NoGift[nNpcId]["ActivetyMapId"] = tInfo["Pos"]["NoGift"]["MapId"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["ActivetyPosX"] = tInfo["Pos"]["NoGift"]["PosX"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["ActivetyPosY"] = tInfo["Pos"]["NoGift"]["PosY"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["AfterActivetyMapId"] = 5000
		MoveNpc_NpcInfo_NoGift[nNpcId]["AfterActivetyPosX"] = 100
		MoveNpc_NpcInfo_NoGift[nNpcId]["AfterActivetyPosY"] = 100
		MoveNpc_NpcInfo_NoGift[nNpcId]["GlobalId"] = tInfo["GlobalId"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["GlobalData"] = tInfo["GlobalData"]
		MoveNpc_NpcInfo_NoGift[nNpcId]["GlobalPos"] = tInfo["GlobalPos"]
	end
end
